CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL,UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.booking_services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100),price_cents integer NOT NULL CHECK(price_cents BETWEEN 0 AND 100000),duration_minutes integer NOT NULL DEFAULT 30 CHECK(duration_minutes BETWEEN 5 AND 240),supplement boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.booking_services TO anon,authenticated; GRANT UPDATE ON public.booking_services TO authenticated; GRANT ALL ON public.booking_services TO service_role;
ALTER TABLE public.booking_services ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_catalog ON public.booking_services FOR SELECT TO anon,authenticated USING(active OR (auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin')));
CREATE POLICY admin_catalog ON public.booking_services FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.booking_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),public_enabled boolean NOT NULL DEFAULT false,durations_validated boolean NOT NULL DEFAULT false,privacy_validated boolean NOT NULL DEFAULT false,privacy_contact text NOT NULL DEFAULT '' CHECK(length(privacy_contact)<=255),retention_days integer NOT NULL DEFAULT 90 CHECK(retention_days BETWEEN 1 AND 3650));
GRANT SELECT ON public.booking_settings TO anon,authenticated; GRANT UPDATE ON public.booking_settings TO authenticated; GRANT ALL ON public.booking_settings TO service_role;
ALTER TABLE public.booking_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_settings ON public.booking_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY admin_settings ON public.booking_settings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.booking_hours(weekday integer PRIMARY KEY CHECK(weekday BETWEEN 0 AND 6),enabled boolean NOT NULL DEFAULT false,opens time NOT NULL DEFAULT '10:00',closes time NOT NULL DEFAULT '19:00',CHECK(opens<closes));
GRANT SELECT ON public.booking_hours TO anon,authenticated; GRANT UPDATE ON public.booking_hours TO authenticated; GRANT ALL ON public.booking_hours TO service_role;
ALTER TABLE public.booking_hours ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_hours ON public.booking_hours FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY admin_hours ON public.booking_hours FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.booking_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,kind text NOT NULL CHECK(kind IN ('appointment','block')),status text NOT NULL DEFAULT 'confirmed' CHECK(status IN ('confirmed','cancelled')),service_ids uuid[] NOT NULL DEFAULT '{}',service_names text NOT NULL DEFAULT '',price_cents integer NOT NULL DEFAULT 0,note text NOT NULL DEFAULT '' CHECK(length(note)<=1000),created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at),EXCLUDE USING gist(tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE(status='confirmed'));
GRANT SELECT ON public.booking_events TO authenticated; GRANT ALL ON public.booking_events TO service_role;
ALTER TABLE public.booking_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_events ON public.booking_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE INDEX booking_event_dates ON public.booking_events(starts_at);
CREATE TABLE public.booking_customers(event_id uuid PRIMARY KEY REFERENCES public.booking_events(id) ON DELETE CASCADE,first_name text NOT NULL CHECK(length(first_name) BETWEEN 1 AND 80),last_name text NOT NULL CHECK(length(last_name) BETWEEN 1 AND 80),phone text NOT NULL CHECK(length(phone) BETWEEN 7 AND 30),email text CHECK(email IS NULL OR length(email)<=255),privacy_version text NOT NULL DEFAULT '2026-12-v1',consented_at timestamptz,source text NOT NULL CHECK(source IN ('public','manual')));
GRANT SELECT ON public.booking_customers TO authenticated; GRANT ALL ON public.booking_customers TO service_role;
ALTER TABLE public.booking_customers ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_customers ON public.booking_customers FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.booking_event_window() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.starts_at AT TIME ZONE 'Europe/Brussels')::date < DATE '2026-12-01' OR (NEW.ends_at AT TIME ZONE 'Europe/Brussels')::date > DATE '2026-12-31' OR NEW.ends_at > (TIMESTAMP '2027-01-01 00:00' AT TIME ZONE 'Europe/Brussels') THEN RAISE EXCEPTION 'DECEMBER_ONLY'; END IF; RETURN NEW; END $$;
CREATE TRIGGER booking_window BEFORE INSERT OR UPDATE ON public.booking_events FOR EACH ROW EXECUTE FUNCTION public.booking_event_window();
CREATE FUNCTION public.booking_slots(p_date date,p_services uuid[]) RETURNS TABLE(starts_at timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE dur integer; h public.booking_hours; cfg public.booking_settings; BEGIN IF p_date<DATE '2026-12-01' OR p_date>DATE '2026-12-31' OR cardinality(p_services) NOT BETWEEN 1 AND 8 THEN RAISE EXCEPTION 'DECEMBER_ONLY'; END IF; SELECT * INTO cfg FROM public.booking_settings WHERE id; IF NOT (cfg.public_enabled AND cfg.durations_validated AND cfg.privacy_validated) AND NOT COALESCE(public.has_role(auth.uid(),'admin'),false) THEN RETURN; END IF; SELECT sum(duration_minutes) INTO dur FROM public.booking_services WHERE id=ANY(p_services) AND active; IF dur IS NULL OR (SELECT count(*) FROM public.booking_services WHERE id=ANY(p_services) AND active)<>cardinality(p_services) THEN RAISE EXCEPTION 'INVALID_SERVICES'; END IF; SELECT * INTO h FROM public.booking_hours WHERE weekday=extract(dow FROM p_date)::integer; IF NOT h.enabled THEN RETURN; END IF; RETURN QUERY SELECT g FROM generate_series((p_date+h.opens) AT TIME ZONE 'Europe/Brussels',((p_date+h.closes) AT TIME ZONE 'Europe/Brussels')-make_interval(mins=>dur),interval '15 minutes') g WHERE g>now() AND NOT EXISTS(SELECT 1 FROM public.booking_events e WHERE e.status='confirmed' AND tstzrange(e.starts_at,e.ends_at,'[)') && tstzrange(g,g+make_interval(mins=>dur),'[)')); END $$;
REVOKE ALL ON FUNCTION public.booking_slots(date,uuid[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.booking_slots(date,uuid[]) TO anon,authenticated,service_role;
CREATE FUNCTION public.create_booking(p_services uuid[],p_start timestamptz,p_first text,p_last text,p_phone text,p_email text,p_consent boolean,p_manual boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cfg public.booking_settings; h public.booking_hours; dur integer; cost integer; names text; event uuid; local_start timestamp; local_end timestamp; BEGIN IF p_manual THEN IF NOT COALESCE(public.has_role(auth.uid(),'admin'),false) THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF; ELSE IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'SERVER_REQUIRED'; END IF; END IF; SELECT * INTO cfg FROM public.booking_settings WHERE id FOR SHARE; IF NOT p_manual AND NOT (cfg.public_enabled AND cfg.durations_validated AND cfg.privacy_validated AND p_consent) THEN RAISE EXCEPTION 'BOOKING_DISABLED'; END IF; IF p_start<=now() OR cardinality(p_services) NOT BETWEEN 1 AND 8 OR p_services IS NULL THEN RAISE EXCEPTION 'INVALID_REQUEST'; END IF; IF length(trim(p_first)) NOT BETWEEN 1 AND 80 OR length(trim(p_last)) NOT BETWEEN 1 AND 80 OR p_phone !~ '^\+?[0-9 () .-]{7,30}$' OR (p_email IS NOT NULL AND (length(p_email)>255 OR p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$')) THEN RAISE EXCEPTION 'INVALID_CONTACT'; END IF; SELECT sum(duration_minutes),sum(price_cents),string_agg(name,' + ' ORDER BY sort_order) INTO dur,cost,names FROM public.booking_services WHERE id=ANY(p_services) AND active; IF dur IS NULL OR (SELECT count(*) FROM public.booking_services WHERE id=ANY(p_services) AND active)<>cardinality(p_services) OR (SELECT count(*) FROM public.booking_services WHERE id=ANY(p_services) AND NOT supplement AND active)<>1 THEN RAISE EXCEPTION 'INVALID_SERVICES'; END IF; local_start:=p_start AT TIME ZONE 'Europe/Brussels'; local_end:=(p_start+make_interval(mins=>dur)) AT TIME ZONE 'Europe/Brussels'; IF local_start::date<DATE '2026-12-01' OR local_end::date>DATE '2026-12-31' OR local_start::date<>local_end::date OR extract(second FROM local_start)<>0 OR extract(minute FROM local_start)::integer%15<>0 THEN RAISE EXCEPTION 'DECEMBER_ONLY'; END IF; SELECT * INTO h FROM public.booking_hours WHERE weekday=extract(dow FROM local_start)::integer FOR SHARE; IF NOT h.enabled OR local_start::time<h.opens OR local_end::time>h.closes THEN RAISE EXCEPTION 'CLOSED'; END IF; INSERT INTO public.booking_events(starts_at,ends_at,kind,service_ids,service_names,price_cents) VALUES(p_start,p_start+make_interval(mins=>dur),'appointment',p_services,names,cost) RETURNING id INTO event; INSERT INTO public.booking_customers(event_id,first_name,last_name,phone,email,consented_at,source) VALUES(event,trim(p_first),trim(p_last),p_phone,p_email,CASE WHEN p_consent THEN now() ELSE NULL END,CASE WHEN p_manual THEN 'manual' ELSE 'public' END); RETURN event; END $$;
REVOKE ALL ON FUNCTION public.create_booking(uuid[],timestamptz,text,text,text,text,boolean,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_booking(uuid[],timestamptz,text,text,text,text,boolean,boolean) TO authenticated,service_role;
CREATE FUNCTION public.admin_block(p_start timestamptz,p_end timestamptz,p_note text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE event uuid; BEGIN IF NOT COALESCE(public.has_role(auth.uid(),'admin'),false) THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF; IF p_end<=p_start OR p_end-p_start>interval '31 days' OR length(p_note)>1000 THEN RAISE EXCEPTION 'INVALID_REQUEST'; END IF; INSERT INTO public.booking_events(starts_at,ends_at,kind,note) VALUES(p_start,p_end,'block',p_note) RETURNING id INTO event; RETURN event; END $$;
REVOKE ALL ON FUNCTION public.admin_block(timestamptz,timestamptz,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.admin_block(timestamptz,timestamptz,text) TO authenticated;
CREATE FUNCTION public.admin_cancel(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT COALESCE(public.has_role(auth.uid(),'admin'),false) THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF; UPDATE public.booking_events SET status='cancelled' WHERE id=p_id; IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; END $$;
REVOKE ALL ON FUNCTION public.admin_cancel(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.admin_cancel(uuid) TO authenticated;